ifn_med = (
    ifn.groupby(
        [
            "model",
            "cells",
            "unit_a",
            "unit_b",
            "fold"
        ]
    )
    .spearman
    .mean()
    .groupby(
        [
            "model",
            "cells",
            "unit_a",
            "unit_b"
        ]
    )
    .median()
    .reset_index()
)

h4 = float(
    ifn_med.query(
        "model == 'D' and cells == 'all'"
    )
    .spearman
    .iloc[0]
)


lines += [
    "## H3 - overlap and latent correlation",
    "",
    table(
        ov.round(3)
    ),
    "",
    f"**H3 (model D, all cells): rho = "
    f"{rho[('D', 'all')]:.3f} -> "
    f"{'SUPPORTED' if rho[('D', 'all')] > 0 else 'NOT SUPPORTED'}.** "
    "Pairs are not independent; rho is descriptive.",
    ""
]


if os.path.exists(
    "results/overlap/purity_vs_overlap.csv"
):

    pv = pd.read_csv(
        "results/overlap/purity_vs_overlap.csv"
    )

    from scipy.stats import spearmanr

    lines += [
        "Secondary: Spearman rho(max Jaccard with any pathway, attribution purity), "
        f"model D: "
        f"{spearmanr(
            pv.max_jaccard,
            pv.median_attribution_purity
        ).statistic:.3f} "
        f"over {len(pv)} pathways.",
        ""
    ]


# H4: IFN-alpha / IFN-gamma entanglement
lines += [
    "## H4 - IFN-alpha / IFN-gamma entanglement "
    "(and D2 module correlations)",
    "",
    table(ifn_med),
    "",
    f"**H4 (model D, all held-out cells): "
    f"median Spearman = {h4:.3f} -> "
    f"{'SUPPORTED' if h4 >= 0.5 else 'NOT SUPPORTED'}** "
    "(criterion >= 0.5).",
    ""
]


# Internal comparison of D2 and D
